<!--
	ContentFrame.vue
	----------------

	To give the site a unique style twist, I will add a frame on top of everything
	that that has some decorative elements.

	Mainly we'll have rounded corners that fill in the teal.

	We'll need to move it with the side bar, but otherwise it should be full screen.
-->
<script setup>

// vue
import { computed } from 'vue';

// app imports
import { useHamburger } from '../composables/useHamburger';
import { useSearch } from '../composables/useSearch';

// components
import ContainerCustom3D from './ContainerCustom3D.vue';

// composables
const { isOpen } = useHamburger();
const { searchActive } = useSearch();

// change sidebar width based on search state
const sideBarWidth = computed(() => {
	if (searchActive.value) {
		return '396px';
	}
	return '256px';
});

</script>
<template>

	<div
		class="main-frame-clip-boundary"
		:class="{ 'is-open': isOpen }"
		:style="{ '--sidebar-w': sideBarWidth }"
	>
		<div
			class="main-frame"
			:class="{ 'is-open': isOpen }"
		>
			<div class="tl"></div>
			<div class="bl"></div>
			<div class="tr"></div>
			<div class="br"></div>

			<!-- this will be for referencing the screen -->
			<ContainerCustom3D
				:build-fn="()=>{}"
				class="frame-ref"
				name="main_frame_ref"
			/>
		</div>
	</div>

</template>
<style lang="scss" scoped>

	.main-frame-clip-boundary {

		// don't interfere with pointer events on the content, but still be above the canvas
		pointer-events: none;

		// fill viewport
		position: fixed;
		inset: -1px -1px -1px -1px;
		z-index: 45;

		// don't let shadow escape
		overflow: clip;

		// frame to frame the content area
		.main-frame {

			// fill viewport
			position: fixed;
			inset: -1px -1px -1px -1px;

			// inner shadow
			box-shadow: inset 0px 0px 20px 5px rgba(0, 0, 0, 1.25);

			// nice rounded corners and border
			border-radius: 55px 55px 0px 55px;
			border: 5px solid var(--color-primary);

			transition: left 220ms linear;
			@media (min-width: 900px) {
				left: var(--sidebar-w);
			}
			&.is-open {
				left: var(--sidebar-w);
			}

			// the corner decorations, which are just background images in divs
			// to fill the teal
			.tl, .bl, .tr, .br {
				position: absolute;
				width: 54px;
				height: 54px;
				background-color: var(--color-primary);
				mask-size: cover;
			}

			.tl {
				top: -4px;
				left: -4px;
				mask-image: url(data:image/png;base64,);
			}

			.bl {
				bottom: -5px;
				left: -4px;
				mask-image: url(data:image/png;base64,);
			}

			.tr {
				top: -4px;
				right: -4px;
				mask-image: url(data:image/png;base64,);
			}

			.br {
				bottom: -4px;
				right: -4px;

				mask-image: url(data:image/png;base64,);
			}

			.frame-ref {

				// width: 100% !important;
				// height: 600px !important;
				width: initial !important;
				height: initial !important;
				position: absolute;
				inset: 0px 0px 0px 0px;

				// for debug
				// border: 10px solid red;

			}// .frame-ref

		}// .main-frame

	}// .main-frame-clip-boundary

</style>
